def find_path(graph, start, goal):
    def dfs(graph, current, path, visited):
        # Mark the current node as visited
        visited.add(current)
        path.append(current)

        # If the current node is the goal, return the path
        if current == goal:
            return True, path

        # Explore each neighbor
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                # Recursively call dfs if the neighbor is not visited
                if dfs(graph, neighbor, path.copy(), visited.copy()):
                    return True, path.copy()

        # Remove the current node from the path and visited set
        path.pop()
        visited.remove(current)
        return False, None

    # Start DFS from the start node
    visited = set()
    path = []
    if start not in visited:
        if dfs(graph, start, path, visited):
            return path
        else:
            return None
    else:
        return None

