def find_path(graph, start, goal):
    if start == goal:
        return [start]  # Path found when start and goal are the same node

    visited = set()  # To keep track of visited nodes
    path_stack = [[start]]  # Stack to keep track of paths

    while path_stack:
        current_path = path_stack.pop()  # Pop a path from the stack
        current_node = current_path[-1]  # Last node of the current path

        if current_node not in visited:
            visited.add(current_node)
            neighbors = graph.get(current_node, [])
            for neighbor in neighbors:
                new_path = current_path + [neighbor]  # Create a new path
                if neighbor == goal:
                    return new_path  # Goal node found
                path_stack.append(new_path)  # Add new path to the stack

    return None  # Goal node is unreachable
