from collections import deque

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Track parent nodes and visited nodes for the path to be reconstructed
    parent = {start: None}
    visited = {start: True}

    # Enqueue start node
    queue = deque([(start, [])])

    while queue:
        current, path = queue.popleft()

        if current == goal:
            # Reconstruct the path by following parent pointers
            reconstructed_path = [goal]
            while goal is not None:
                goal = parent[goal]
                reconstructed_path.append(goal)
            return reversed(reconstructed_path)

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited[neighbor] = True
                parent[neighbor] = current
                queue.append((neighbor, path + [current]))

    return None

